package com.nexodb.ui;

import com.nexodb.db.*;
import com.nexodb.util.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.awt.event.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import static com.nexodb.util.I18n.tr;

/** Searchable, read-only data dictionary with lazy keys/indexes and cancellable complete exports. */
final class DataDictionaryPanel extends JPanel {
    private final JdbcSession origin;private final String database;private final Consumer<SchemaItem> structure;private final Runnable diagram;
    private final DefaultListModel<DataDictionaryService.Table> names=new DefaultListModel<>();private final JList<DataDictionaryService.Table> tables=new JList<>(names);private final JTextField search=new JTextField();private final JLabel status=new JLabel(" "),summary=new JLabel(" ");private final JTextArea description=new JTextArea(4,50);
    private final DefaultTableModel columnModel=model(new Object[]{"PK",tr("Columna"),tr("Tipo"),"NULL",tr("Predeterminado"),tr("Auto incremento"),tr("Comentario")});
    private final DefaultTableModel indexModel=model(new Object[]{tr("Índice"),tr("Único"),tr("Columnas")});
    private final DefaultTableModel relationModel=model(new Object[]{tr("Relación"),tr("Columnas hijas"),tr("Tabla referenciada"),tr("Columnas referenciadas"),"ON UPDATE","ON DELETE"});
    private final JTable columns=new JTable(columnModel),indexes=new JTable(indexModel),relations=new JTable(relationModel);private final JButton refresh=button("Actualizar"),cancel=button("Cancelar"),exportMarkdown=button("Exportar Markdown…"),exportCsv=button("Exportar CSV…"),openStructure=button("Editar estructura…"),openDiagram=button("Abrir en diagrama");
    private final Map<String,DataDictionaryService.Table> detailed=new HashMap<>();private DataDictionaryService.Dictionary dictionary;private SwingWorker<?,Void> worker;private BackgroundOperations.Operation operation;private volatile JdbcSession.ReadLease lease;private boolean disposed;

    DataDictionaryPanel(JdbcSession origin,String database,Consumer<SchemaItem> structure,Runnable diagram){
        super(new BorderLayout(7,7));this.origin=origin;this.database=database;this.structure=structure;this.diagram=diagram;setName("data-dictionary");setBorder(new EmptyBorder(8,8,8,8));
        JToolBar bar=new JToolBar();bar.setFloatable(false);bar.add(refresh);bar.add(cancel);bar.addSeparator();bar.add(exportMarkdown);bar.add(exportCsv);bar.addSeparator();bar.add(openStructure);bar.add(openDiagram);bar.add(Box.createHorizontalGlue());bar.add(summary);add(bar,BorderLayout.NORTH);
        JPanel left=new JPanel(new BorderLayout(4,4));UiLanguage.placeholder(search,"Buscar tabla, columna o comentario…");left.add(search,BorderLayout.NORTH);tables.setName("dictionary-tables");tables.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);tables.setCellRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> list,Object value,int index,boolean selected,boolean focus){super.getListCellRendererComponent(list,value,index,selected,focus);if(value instanceof DataDictionaryService.Table table)setText((table.type().equals("VIEW")?"◉ ":"▦ ")+table.qualified()+(table.remarks().isBlank()?"":"  · "+oneLine(table.remarks())));return this;}});left.add(new JScrollPane(tables));
        description.setName("dictionary-description");description.setEditable(false);description.setLineWrap(true);description.setWrapStyleWord(true);description.setBorder(new EmptyBorder(8,8,8,8));JTabbedPane tabs=new JTabbedPane();tabs.addTab(tr("Columnas"),scroll(columns));tabs.addTab(tr("Índices"),scroll(indexes));tabs.addTab(tr("Relaciones"),scroll(relations));JPanel detail=new JPanel(new BorderLayout(4,4));detail.add(new JScrollPane(description),BorderLayout.NORTH);detail.add(tabs);JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,left,detail);split.setDividerLocation(330);split.setResizeWeight(.22);add(split);
        status.setBorder(new EmptyBorder(4,4,2,4));add(status,BorderLayout.SOUTH);for(JTable table:List.of(columns,indexes,relations)){table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);table.setRowHeight(25);table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);for(int i=0;i<table.getColumnCount();i++)table.getColumnModel().getColumn(i).setPreferredWidth(i==table.getColumnCount()-1?260:150);}
        refresh.addActionListener(e->refresh());cancel.addActionListener(e->cancel());exportMarkdown.addActionListener(e->export(true));exportCsv.addActionListener(e->export(false));openStructure.addActionListener(e->openStructure());openDiagram.addActionListener(e->diagram.run());tables.addListSelectionListener(e->{if(!e.getValueIsAdjusting())select();});tables.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)openStructure();}});search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){private void changed(){filter();}public void insertUpdate(javax.swing.event.DocumentEvent e){changed();}public void removeUpdate(javax.swing.event.DocumentEvent e){changed();}public void changedUpdate(javax.swing.event.DocumentEvent e){changed();}});actions(false);refresh();
    }
    JdbcSession origin(){return origin;}String database(){return database;}
    void disposePanel(){disposed=true;cancel();}
    private static DefaultTableModel model(Object[] columns){return new DefaultTableModel(columns,0){public boolean isCellEditable(int r,int c){return false;}};}
    private static JScrollPane scroll(JTable table){return new JScrollPane(table);}
    private static JButton button(String key){return UiLanguage.text(new JButton(tr(key)),UiLanguage.key(key));}
    private void refresh(){
        if(disposed||worker!=null&&!worker.isDone()||!origin.isOpen())return;actions(false);status.setText(tr("Leyendo tablas, columnas y comentarios…"));BackgroundOperations.Operation active=BackgroundOperations.create(BackgroundOperations.Kind.RELOAD,tr("Diccionario de datos"),origin.profile().name(),this::cancelWorker,this::refresh);operation=active;worker=new SwingWorker<DataDictionaryService.Dictionary,Void>(){protected DataDictionaryService.Dictionary doInBackground()throws Exception{active.awaitTurn();try(JdbcSession.ReadLease read=origin.borrowReadOnly(10_000)){lease=read;return DataDictionaryService.read(read.session(),database);}finally{lease=null;}}protected void done(){try{if(isCancelled()){active.cancelled(tr("Lectura cancelada."));return;}dictionary=get();active.complete(dictionary.tables().size()+tr(" objetos"));detailed.clear();filter();summary.setText(dictionary.tables().size()+tr(" objetos · ")+dictionary.tables().stream().mapToInt(table->table.columns().size()).sum()+tr(" columnas"));status.setText(dictionary.warnings().isEmpty()?tr("Diccionario actualizado. Selecciona una tabla para leer claves, índices y relaciones."):String.join(" · ",dictionary.warnings()));}catch(Exception error){active.fail(error);status.setText(tr("No se pudo leer el diccionario: ")+message(error));dictionary=null;names.clear();}finally{if(worker==this){worker=null;operation=null;}actions(dictionary!=null);}}};actions(false);worker.execute();
    }
    private void select(){
        DataDictionaryService.Table selected=tables.getSelectedValue();render(selected);if(selected==null||selected.detailed()||!selected.type().equals("TABLE")||worker!=null&&!worker.isDone())return;String key=key(selected);if(detailed.containsKey(key)){render(detailed.get(key));return;}status.setText(tr("Leyendo claves, índices y relaciones de ")+selected.qualified()+"…");BackgroundOperations.Operation active=BackgroundOperations.create(BackgroundOperations.Kind.RELOAD,tr("Detalles del diccionario"),origin.profile().name(),this::cancelWorker,null);operation=active;worker=new SwingWorker<DataDictionaryService.Table,Void>(){protected DataDictionaryService.Table doInBackground()throws Exception{active.awaitTurn();try(JdbcSession.ReadLease read=origin.borrowReadOnly(10_000)){lease=read;return DataDictionaryService.details(read.session(),selected);}finally{lease=null;}}protected void done(){try{if(isCancelled()){active.cancelled(tr("Lectura cancelada."));return;}DataDictionaryService.Table result=get();active.complete(result.indexes().size()+tr(" índices · ")+result.relations().size()+tr(" relaciones"));detailed.put(key,result);if(tables.getSelectedValue()==selected)render(result);status.setText(tr("Detalles estructurales actualizados."));}catch(Exception error){active.fail(error);status.setText(tr("No se pudieron leer todos los detalles: ")+message(error));}finally{if(worker==this){worker=null;operation=null;}actions(dictionary!=null);}}};actions(false);worker.execute();
    }
    private void render(DataDictionaryService.Table table){
        columnModel.setRowCount(0);indexModel.setRowCount(0);relationModel.setRowCount(0);if(table==null){description.setText(tr("Selecciona una tabla o vista."));actions(dictionary!=null);return;}DataDictionaryService.Table value=detailed.getOrDefault(key(table),table);description.setText(value.qualified()+" · "+value.type()+"\n"+(value.remarks().isBlank()?tr("Sin comentario de tabla."):value.remarks())+"\n\n"+value.columns().size()+tr(" columnas")+(value.detailed()?" · "+value.indexes().size()+tr(" índices · ")+value.relations().size()+tr(" relaciones"):tr(" · leyendo detalles al seleccionar")));description.setCaretPosition(0);for(var column:value.columns())columnModel.addRow(new Object[]{column.primaryKey()?"●":"",column.name(),type(column),column.nullable()?tr("Sí"):tr("No"),column.defaultValue(),"YES".equalsIgnoreCase(column.autoIncrement())?tr("Sí"):"",column.remarks()});for(var index:value.indexes())indexModel.addRow(new Object[]{index.name(),index.unique()?tr("Sí"):tr("No"),String.join(", ",index.columns())});for(var relation:value.relations())relationModel.addRow(new Object[]{relation.name(),String.join(", ",relation.columns()),relation.parent(),String.join(", ",relation.parentColumns()),relation.onUpdate(),relation.onDelete()});if(value.detailed()&&indexModel.getRowCount()==0)indexModel.addRow(new Object[]{tr("Sin índices reportados"),"",""});if(value.detailed()&&relationModel.getRowCount()==0)relationModel.addRow(new Object[]{tr("Sin relaciones salientes"),"","","","",""});actions(dictionary!=null);
    }
    private void filter(){
        DataDictionaryService.Table selected=tables.getSelectedValue();names.clear();if(dictionary==null)return;String needle=normalize(search.getText());for(var table:dictionary.tables()){String haystack=normalize(table.qualified()+" "+table.remarks()+" "+String.join(" ",table.columns().stream().map(column->column.name()+" "+column.type()+" "+column.remarks()).toList()));if(needle.isBlank()||haystack.contains(needle))names.addElement(table);}if(selected!=null)for(int i=0;i<names.size();i++)if(key(names.get(i)).equals(key(selected))){tables.setSelectedIndex(i);return;}if(!names.isEmpty())tables.setSelectedIndex(0);
    }
    private void export(boolean markdown){
        if(dictionary==null||worker!=null&&!worker.isDone())return;JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("diccionario-"+safe(database)+(markdown?".md":".csv")));if(chooser.showSaveDialog(DialogPosition.owner(this))!=JFileChooser.APPROVE_OPTION)return;Path target=chooser.getSelectedFile().toPath();if(Files.exists(target)&&!Confirmations.ask(this,tr("Reemplazar archivo"),target.toString()))return;actions(false);status.setText(tr("Completando claves, índices y relaciones para exportar…"));BackgroundOperations.Operation active=BackgroundOperations.create(BackgroundOperations.Kind.EXPORT,tr("Exportar diccionario de datos"),origin.profile().name(),this::cancelWorker,null);operation=active;worker=new SwingWorker<DataDictionaryService.Dictionary,Void>(){protected DataDictionaryService.Dictionary doInBackground()throws Exception{active.awaitTurn();try(JdbcSession.ReadLease read=origin.borrowReadOnly(10_000)){lease=read;return DataDictionaryService.complete(read.session(),database,percent->{active.progress(percent,tr("Metadatos estructurales"));SwingUtilities.invokeLater(()->status.setText(tr("Preparando diccionario: ")+percent+"%"));});}finally{lease=null;}}protected void done(){try{if(isCancelled()){active.cancelled(tr("Lectura cancelada."));return;}DataDictionaryService.Dictionary complete=get();write(target,markdown?DataDictionaryService.markdown(complete):DataDictionaryService.csv(complete));active.complete(complete.tables().size()+tr(" objetos"));status.setText(tr("Diccionario exportado: ")+target.getFileName());}catch(Exception error){active.fail(error);status.setText(tr("No se pudo exportar: ")+message(error));}finally{if(worker==this){worker=null;operation=null;}actions(dictionary!=null);}}};actions(false);worker.execute();
    }
    private void openStructure(){DataDictionaryService.Table table=tables.getSelectedValue();if(table==null)return;boolean catalog=SchemaMetadataReader.catalogNamespace(origin.profile().type());structure.accept(new SchemaItem(table.type().equals("VIEW")?SchemaItem.Kind.VIEW:SchemaItem.Kind.TABLE,catalog?database:null,catalog?null:database,table.name(),table.remarks()));}
    private void cancel(){BackgroundOperations.Operation active=operation;if(active!=null)active.requestCancel();else cancelWorker();status.setText(tr("Lectura cancelada."));}
    private void cancelWorker(){SwingWorker<?,Void> active=worker;if(active!=null)active.cancel(true);JdbcSession.ReadLease current=lease;if(current!=null)try{current.session().cancel();}catch(Exception ignored){}}
    private void actions(boolean available){boolean idle=worker==null||worker.isDone();refresh.setEnabled(idle);cancel.setEnabled(!idle);exportMarkdown.setEnabled(available&&idle);exportCsv.setEnabled(available&&idle);openStructure.setEnabled(available&&idle&&tables.getSelectedValue()!=null);openDiagram.setEnabled(available&&idle);}
    private static String type(DataDictionaryService.Column c){String upper=c.type().toUpperCase(Locale.ROOT);return c.type()+(c.size()>0&&(upper.contains("CHAR")||upper.contains("BINARY")||upper.equals("DECIMAL")||upper.equals("NUMERIC"))?"("+c.size()+(c.scale()>0?","+c.scale():"")+")":"");}
    private static String key(DataDictionaryService.Table table){return Objects.toString(table.catalog(),"")+"\u0000"+Objects.toString(table.schema(),"")+"\u0000"+table.name();}
    private static String normalize(String value){return java.text.Normalizer.normalize(Objects.toString(value,"").toLowerCase(Locale.ROOT),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","");}
    private static String oneLine(String value){String text=value.replaceAll("[\\r\\n]+"," ").trim();return text.length()>60?text.substring(0,59)+"…":text;}
    private static String safe(String value){String text=Objects.toString(value,"base").replaceAll("[^A-Za-z0-9._-]+","-");return text.isBlank()?"base":text;}
    private static String message(Throwable error){while(error.getCause()!=null)error=error.getCause();return Objects.toString(error.getMessage(),error.getClass().getSimpleName());}
    private static void write(Path target,String content)throws Exception{Path absolute=target.toAbsolutePath();Path parent=absolute.getParent();if(parent!=null)Files.createDirectories(parent);Path temporary=Files.createTempFile(parent,absolute.getFileName().toString(),".tmp");try{Files.writeString(temporary,content,StandardCharsets.UTF_8);try{Files.move(temporary,absolute,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ignored){Files.move(temporary,absolute,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temporary);}}
}
